  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Business and Entrepreneurship$j$, $j${"readings": [{"title": "Proverbs 31 (King James Version)", "url": "/portal/bible/Proverbs/31"}], "body": "An entrepreneur sees a need, gathers land, labor and capital, and takes a risk to meet it. Businesses are the engines that turn ideas into goods and jobs. Proverbs 31:16 describes a woman who considereth a field, and buyeth it: with the fruit of her hands she planteth a vineyard. She is a model of wise enterprise.\n\nBusinesses take four common legal forms. A sole proprietorship has one owner who keeps all profit and bears all risk and debt. A partnership has two or more owners who share profit and responsibility. A corporation is a separate legal entity owned by stockholders, who are protected from personal liability for the company's debts. A limited liability company, called an LLC, blends the protection of a corporation with simpler rules. Many small businesses in Florida are LLCs.\n\nProfit equals total revenue minus total costs. Revenue is the money a business takes in from sales. Costs include fixed costs, such as rent, which stay the same however much is sold, and variable costs, such as materials, which rise with output. A business that earns less than its costs takes a loss and may close.\n\nEntrepreneurs face risk, but they also create jobs and bring new products. A business plan helps by stating the product, the customers, the competition, the costs and the way the owner will earn a profit. Proverbs 14:23 says that in all labour there is profit: but the talk of the lips tendeth only to penury.\n\nYour task: (1) Name the four forms of business and one advantage of each. (2) Define profit, fixed cost and variable cost. (3) Describe a small business you could start and list what its business plan would need.\n\nFlorida standards: SS.912.E.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.E.2", "script": "Welcome back. Listen, behind every job in your neighborhood is somebody who saw a need and took a risk.\n\nAn entrepreneur gathers land, labor and capital to meet a need. Proverbs 31:16 describes a woman who considered a field and bought it, and with the fruit of her hands planted a vineyard. That is wise enterprise.\n\nNow watch this. There are four common forms of business. A sole proprietorship has one owner who keeps all the profit and all the risk. A partnership has two or more owners who share both. A corporation is a separate legal body owned by stockholders, who are not personally liable for its debts. And an LLC, a limited liability company, blends that protection with simpler rules.\n\nLook at profit. Profit equals total revenue minus total costs. Fixed costs, like rent, stay the same however much you sell. Variable costs, like materials, rise as you make more. If costs beat revenue, that is a loss.\n\nA business plan names the product, the customers, the competition, the costs and how you will earn a profit.\n\nYour task is to name the four forms, define profit and the two kinds of cost, and sketch a small business. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Business and Entrepreneurship$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Labor, Wages and Careers$j$, $j${"readings": [{"title": "Colossians 3 (King James Version)", "url": "/portal/bible/Colossians/3"}], "body": "Labor is the work people do in exchange for pay. Wages are set largely by supply and demand in the labor market. Jobs that need rare skills, long training or hard conditions usually pay more, because fewer workers can fill them. A worker can raise his or her pay by building human capital, which is the knowledge, skill and health a person brings to work. Education, training and experience are investments in human capital.\n\nSpecialization means focusing on one task, and the division of labor splits a big job among many workers. Together they raise productivity, which is the output per worker. Higher productivity makes higher wages possible. Colossians 3:23 teaches, And whatsoever ye do, do it heartily, as to the Lord, and not unto men. Proverbs 22:29 adds, Seest thou a man diligent in his business? he shall stand before kings.\n\nWorkers have some legal protections. The National Labor Relations Act of 1935 protects the right to form a labor union and to bargain together. The Fair Labor Standards Act of 1938 set the first federal minimum wage, required overtime pay at one and one half times the regular rate for work over forty hours in most jobs, and limited child labor. The federal minimum wage is 7.25 dollars an hour, and Florida's constitution sets a higher state minimum that rises on a schedule, so students should check the current rate with the Florida Department of Commerce.\n\nChoosing a career means weighing pay, interest, training time and demand for the work. Technology changes jobs quickly, so lifelong learning matters.\n\nYour task: (1) Define human capital and give two ways to build it. (2) Explain how specialization raises productivity. (3) Name one law that protects workers and tell what it does.\n\nFlorida standards: SS.912.E.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.E.2", "script": "Welcome back. Listen, the most valuable thing you own is not in your wallet. It is in your mind and your hands.\n\nLabor is the work people do for pay, and wages are set largely by supply and demand. Jobs that need rare skills or long training usually pay more, because fewer people can do them. That is why we talk about human capital, the knowledge, skill and health you bring to work. School, training and experience are investments in it.\n\nNow watch this. Specialization means focusing on one task. The division of labor splits a big job among many workers. Together they raise productivity, the output per worker, and higher productivity makes higher wages possible.\n\nColossians 3:23 says, whatsoever ye do, do it heartily, as to the Lord. And Proverbs 22:29 says a diligent man shall stand before kings.\n\nLook at the law. In 1935 the National Labor Relations Act protected the right to form unions. In 1938 the Fair Labor Standards Act set the first federal minimum wage, required overtime after forty hours, and limited child labor. Florida sets its own higher minimum, so always check the current rate.\n\nYour task is to define human capital, explain specialization, and name a law that protects workers. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Labor, Wages and Careers$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 Money, Banking and the Federal Reserve$j$, $j${"readings": [{"title": "Proverbs 22 (King James Version)", "url": "/portal/bible/Proverbs/22"}], "body": "Before money, people used barter, trading goods directly. Barter fails when each person does not want what the other has. Money solves this by doing three jobs: it is a medium of exchange that everyone accepts, a unit of account that lets us measure value, and a store of value that holds worth over time. Good money is durable, portable, divisible, scarce and accepted. The United States dollar is fiat money, which means it has value because the government declares it legal tender and people trust it, not because it is backed by gold.\n\nBanks take deposits and make loans. They pay interest to savers and charge a higher interest rate to borrowers, and the difference helps cover costs and earn profit. A bank keeps part of deposits on hand and lends the rest, which expands the money supply. After the bank failures of the Great Depression, Congress created the Federal Deposit Insurance Corporation, the FDIC, in 1933. It insures deposits up to 250,000 dollars per depositor, per insured bank, for each ownership category.\n\nThe nation's central bank is the Federal Reserve System, created in 1913. It has a Board of Governors of seven members in Washington, twelve regional banks, and the Federal Open Market Committee, which sets monetary policy. Its goals are maximum employment and stable prices. It guides the economy by buying and selling government securities, called open market operations, by setting the discount rate it charges banks, and by steering the federal funds rate.\n\nProverbs 22:7 warns, The rich ruleth over the poor, and the borrower is servant to the lender. Borrow with care.\n\nYour task: (1) Name the three jobs of money. (2) Explain how a bank earns money on loans. (3) Describe two jobs of the Federal Reserve.\n\nFlorida standards: SS.912.E.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.E.3", "script": "Welcome back. Listen, money is one of the greatest inventions in history, and few people can explain what it really is.\n\nBefore money there was barter, and barter breaks down when I do not want what you have. Money solves that with three jobs. It is a medium of exchange, a unit of account and a store of value. The dollar is fiat money. It has value because the government declares it legal tender and people trust it.\n\nNow watch this. Banks take deposits and make loans. They pay savers a little interest and charge borrowers more, and the difference pays their costs and earns a profit. After the bank failures of the Great Depression, Congress created the FDIC in 1933. It insures deposits up to 250,000 dollars per depositor, per insured bank, for each ownership category.\n\nLook at the Federal Reserve. Congress created it in 1913. It has a Board of Governors of seven members, twelve regional banks, and the Federal Open Market Committee. Its goals are maximum employment and stable prices. Its tools include open market operations, the discount rate, and steering the federal funds rate.\n\nRemember Proverbs 22:7. The borrower is servant to the lender.\n\nYour task is to name the three jobs of money, explain how banks earn from loans, and describe two jobs of the Fed. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 Money, Banking and the Federal Reserve$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 The Role of Government in the Economy$j$, $j${"readings": [{"title": "Nehemiah 5 (King James Version)", "url": "/portal/bible/Nehemiah/5"}], "body": "Even in a market economy, government has important jobs. It protects property rights and enforces contracts, so people can trade with trust. It provides public goods, which are goods that everyone shares and that no one can easily be kept from using, such as national defense and lighthouses. Private firms will not provide them for profit because people can use them without paying, which is called the free rider problem.\n\nGovernment also deals with externalities, which are side effects on people who did not take part in a transaction. Pollution from a factory is a negative externality, and government may set rules or fees. A vaccination or an education brings a positive externality, and government may support it. Government also regulates to protect consumers, keeps competition fair, and provides a safety net.\n\nGovernments pay for these services through taxes. The federal government collects mainly the income tax, made legal by the Sixteenth Amendment in 1913, and payroll taxes. Under the Federal Insurance Contributions Act, an employee pays 6.2 percent for Social Security and 1.45 percent for Medicare, and the employer pays the same amount. States and cities rely on sales taxes, property taxes and fees. Florida has no state personal income tax, and its sales tax is 6 percent at the state level, plus local additions in many counties.\n\nA tax can be progressive, taking a larger share from higher incomes, proportional, taking the same share from all, or regressive, taking a larger share from lower incomes. In Nehemiah 5, the prophet confronted rich men who charged heavy interest and seized land, and he demanded that they restore what they had taken. Justice in economics matters to God.\n\nYour task: (1) Define public good, free rider and externality. (2) Name three taxes and who collects each. (3) Explain the difference between a progressive and a regressive tax.\n\nFlorida standards: SS.912.E.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.E.3", "script": "Welcome back. Listen, even a free market needs a referee.\n\nGovernment protects property rights and enforces contracts, so people can trade with trust. It provides public goods, like national defense, that everyone shares and no one can easily be kept from using. Private firms will not provide them for profit because of the free rider problem. People can enjoy them without paying.\n\nNow watch this. An externality is a side effect on someone who was not part of the deal. Pollution from a factory is a negative externality. A good education is a positive one.\n\nLook at how government pays for its work. The federal government collects mainly the income tax, legal since the Sixteenth Amendment in 1913, and payroll taxes. An employee pays 6.2 percent for Social Security and 1.45 percent for Medicare, and the employer pays the same. States and cities depend on sales taxes, property taxes and fees. Florida has no state personal income tax, and its state sales tax is 6 percent, with local additions in many counties.\n\nA progressive tax takes a larger share from higher incomes. A regressive tax takes a larger share from lower incomes.\n\nIn Nehemiah 5 the prophet demanded that rich men stop charging heavy interest and restore the land they seized. Justice matters to God.\n\nYour task is to define public good, free rider and externality, name three taxes, and compare progressive and regressive taxes. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 The Role of Government in the Economy$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Business, Money and Government$j$, $j${"prompt": "Write a report of at least 250 words on business, money and government. Use complete sentences and label each part. Proverbs 22:7 says, The rich ruleth over the poor, and the borrower is servant to the lender.\n\nPart 1: Describe a business you could start. Name its legal form, one fixed cost, one variable cost and how it would earn a profit.\nPart 2: Explain how education and training build human capital and raise wages.\nPart 3: Explain the three jobs of money and how banks and the FDIC protect savers.\nPart 4: Describe two goals and two tools of the Federal Reserve.\nPart 5: Explain one public good and one externality, and describe how a tax pays for government services.", "rubric": "100 points. Part 1: 20 points. Part 2: 15 points. Part 3: 20 points. Part 4: 20 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Business, Money and Government$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Work, Money and Justice$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells what career you would like to study for and what human capital you will need, (2) explains one way you will use banks wisely, (3) tells whether you think a business owner or government should do more to help workers, and why, and (4) connects your answer to Colossians 3:23, which says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Should the minimum wage be higher, lower or the same? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Work, Money and Justice$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Business and Entrepreneurship$j$, $j${"questions": [{"q": "Profit equals:", "options": ["Wages plus taxes", "Total revenue minus total costs", "Revenue plus costs", "Total costs minus revenue"]}, {"q": "Which business form protects owners from personal liability and is owned by stockholders?", "options": ["Corporation", "Barter group", "Partnership with no agreement", "Sole proprietorship"]}, {"q": "Monthly rent for a shop is an example of a:", "options": ["Subsidy", "Revenue", "Fixed cost", "Variable cost"]}, {"q": "A sole proprietorship has:", "options": ["Government owners", "No owner", "One owner who bears all the risk", "Many stockholders"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Business and Entrepreneurship$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,2,2}'::int[], array[$j$A business earns profit when revenue is greater than costs.$j$,$j$Corporate stockholders are not personally liable for company debts.$j$,$j$Fixed costs do not change with the amount sold.$j$,$j$The owner keeps the profit and carries the debt.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Business and Entrepreneurship$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Labor, Wages and Careers$j$, $j${"questions": [{"q": "Human capital is:", "options": ["Money in a bank", "A company's machines", "A tax on wages", "The knowledge and skills a worker brings to a job"]}, {"q": "Productivity means:", "options": ["Output per worker", "The number of workers", "The size of a building", "The price of a good"]}, {"q": "The Fair Labor Standards Act of 1938 set the first:", "options": ["Federal minimum wage", "Income tax", "Tariff", "National bank"]}, {"q": "Overtime pay under federal law is generally owed after how many hours in a week?", "options": ["Thirty", "Sixty", "Forty", "Fifty five"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Labor, Wages and Careers$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,0,2}'::int[], array[$j$Education and training build human capital.$j$,$j$Higher productivity allows higher wages.$j$,$j$It also required overtime pay and limited child labor.$j$,$j$Most covered workers earn time and a half after forty hours.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Labor, Wages and Careers$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Money, Banking and the Federal Reserve$j$, $j${"questions": [{"q": "Which is one of the three jobs of money?", "options": ["Medium of exchange", "Form of government", "Source of taxes", "Type of loan"]}, {"q": "The FDIC was created in:", "options": ["1933", "1971", "1776", "1913"]}, {"q": "The Federal Reserve System was created in:", "options": ["1913", "1933", "1987", "1863"]}, {"q": "Fiat money has value because:", "options": ["It is printed in color", "It is rare", "The government declares it legal tender and people trust it", "It is made of gold"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Money, Banking and the Federal Reserve$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,0,2}'::int[], array[$j$Money is a medium of exchange, a unit of account and a store of value.$j$,$j$It was created after the bank failures of the Great Depression.$j$,$j$Congress passed the Federal Reserve Act in 1913.$j$,$j$The dollar is not backed by a metal.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Money, Banking and the Federal Reserve$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: The Role of Government in the Economy$j$, $j${"questions": [{"q": "A good that everyone shares and no one can easily be kept from using is a:", "options": ["Private good", "Barter good", "Luxury", "Public good"]}, {"q": "Factory pollution is an example of a:", "options": ["Negative externality", "Public good", "Subsidy", "Tariff"]}, {"q": "The Sixteenth Amendment made legal the:", "options": ["Federal income tax", "Tariff", "Property tax", "Sales tax"]}, {"q": "Which statement about Florida is correct?", "options": ["It has no state personal income tax", "It taxes only imports", "It has the highest income tax", "It has no sales tax"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: The Role of Government in the Economy$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,0,0}'::int[], array[$j$National defense is a public good.$j$,$j$It harms people outside the transaction.$j$,$j$It was ratified in 1913.$j$,$j$Florida's constitution bars a state personal income tax.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: The Role of Government in the Economy$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Business, Money and Government$j$, $j${"questions": [{"q": "A business owned by stockholders is a:", "options": ["Partnership", "Corporation", "Sole proprietorship", "Cooperative of one"]}, {"q": "Which raises a worker's human capital?", "options": ["Education and training", "A tariff", "A bank loan", "A higher price on goods"]}, {"q": "Federal overtime pay is generally one and one half times the regular rate after:", "options": ["Sixty hours", "Forty hours", "Twenty hours", "Eight hours"]}, {"q": "Money that has value because a government declares it legal tender is:", "options": ["Commodity money", "Fiat money", "Barter", "A bond"]}, {"q": "The FDIC insures deposits up to:", "options": ["10,000 dollars per account only", "No limit", "250,000 dollars per depositor, per bank, per ownership category", "1,000 dollars"]}, {"q": "The Federal Reserve's two goals are:", "options": ["Full trade and no banks", "Higher taxes and lower wages", "Maximum employment and stable prices", "More tariffs and fewer jobs"]}, {"q": "A tax that takes a larger share of income from lower earners is:", "options": ["Voluntary", "Regressive", "Progressive", "Proportional"]}, {"q": "National defense is an example of a:", "options": ["Negative externality", "Public good", "Private good", "Barter good"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Business, Money and Government$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,1,1,2,2,1,1}'::int[], array[$j$Stockholders own shares of a corporation.$j$,$j$Skills and knowledge raise productivity and pay.$j$,$j$The Fair Labor Standards Act sets this rule for most jobs.$j$,$j$The dollar is fiat money.$j$,$j$The standard coverage amount is 250,000 dollars.$j$,$j$Congress gave the Fed these goals.$j$,$j$A regressive tax weighs more heavily on low incomes.$j$,$j$Everyone shares it and no one can easily be kept from it.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Business, Money and Government$j$ on conflict (item_id) do nothing;
